+import javax.xml.parsers.ParserConfigurationException;
+import javax.xml.xpath.XPath;
+import javax.xml.xpath.XPathExpression;
+import javax.xml.xpath.XPathExpressionException;
+import javax.xml.xpath.XPathFactory;
+import javax.xml.xpath.XPathVariableResolver;
+import java.io.IOException;
+import java.io.InputStream;
+
+public class UserService {
+
+    private static final String USERS_XML_PATH = "/users.xml";
+
+    public String findUserRoleByUsername(String username) {
+        try {
+            Document document = loadDocument();
+            XPath xpath = createXPath(username);
+            XPathExpression expression = xpath.compile("/users/user[name=$username]/role/text()");
+            String result = expression.evaluate(document);
+            return result.isEmpty() ? null : result;
+        } catch (ParserConfigurationException | SAXException | IOException | XPathExpressionException e) {
+            throw new RuntimeException("Failed to find user role", e);
+        }
+    }
+
+    private Document loadDocument() throws ParserConfigurationException, SAXException, IOException {
+        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
+        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
+        DocumentBuilder builder = factory.newDocumentBuilder();
+        try (InputStream is = getClass().getResourceAsStream(USERS_XML_PATH)) {
+            if (is == null) {
+                throw new IOException("users.xml not found in classpath");
+            }
+            return builder.parse(is);
+        }
+    }
+
+    private XPath createXPath(String username) {
+        XPath xpath = XPathFactory.newInstance().newXPath();
+        xpath.setXPathVariableResolver(new XPathVariableResolver() {
+            @Override
+            public Object resolveVariable(QName variableName) {
+                if (variableName.getLocalPart().equals("username")) {
+                    return username;
+                }
+                return null;
+            }
+        });
+        return xpath;
+    }
+}

